command:
$ErrorActionPreference = 'Stop'
. '.forge-codex/instructions/scripts/Common.ps1'
$evidencePath = '.forge-codex/state/evidence/P16/manager-windows-runtime-checkpoint.json'
$evidence = Get-Content -LiteralPath $evidencePath -Raw | ConvertFrom-Json
$mismatches = [System.Collections.Generic.List[string]]::new()
foreach ($property in $evidence.source_sha256.PSObject.Properties) {
  $actual = Get-FileSha256 -Path $property.Name
  if ($actual -ne [string]$property.Value) { $mismatches.Add("source $($property.Name)") }
}
foreach ($property in $evidence.binary_sha256.PSObject.Properties) {
  $candidate = Get-ChildItem -LiteralPath 'out/build/windows-msvc-x64' -Recurse -File -Filter $property.Name | Select-Object -First 1
  if ($null -eq $candidate) { $mismatches.Add("missing binary $($property.Name)"); continue }
  $actual = Get-FileSha256 -Path $candidate.FullName
  if ($actual -ne [string]$property.Value) { $mismatches.Add("binary $($property.Name)") }
}
foreach ($recordName in @('recorded_build','recorded_validation')) {
  $record = $evidence.$recordName
  $actual = Get-FileSha256 -Path $record.command_record
  if ($actual -ne [string]$record.command_record_sha256) { $mismatches.Add("record $recordName") }
}
if ($mismatches.Count -ne 0) { throw "Evidence hash mismatch: $($mismatches -join ', ')" }
Write-Host "Evidence hash validation passed: $(@($evidence.source_sha256.PSObject.Properties).Count) source, $(@($evidence.binary_sha256.PSObject.Properties).Count) binary, 2 command records."
& '.forge-codex/instructions/scripts/Validate-NoPython.ps1' -WorkspaceRoot 'D:\GitHub\Forge-Conductor-Windows-Edition'
& '.forge-codex/instructions/scripts/Validate-NoAttribution.ps1' -WorkspaceRoot 'D:\GitHub\Forge-Conductor-Windows-Edition'
& '.forge-codex/instructions/scripts/Verify-Ledger.ps1' -WorkspaceRoot 'D:\GitHub\Forge-Conductor-Windows-Edition'
& git.exe diff --check
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$changed = @(& git.exe diff --name-only; & git.exe ls-files --others --exclude-standard) | Sort-Object -Unique
$textExtensions = @('.cpp','.cxx','.cc','.h','.hpp','.ixx','.js','.ts','.json','.jsonl','.md','.ps1','.cmake','.txt')
foreach ($relativePath in $changed) {
  if (-not (Test-Path -LiteralPath $relativePath -PathType Leaf)) { continue }
  $extension = [System.IO.Path]::GetExtension($relativePath).ToLowerInvariant()
  if (($textExtensions -notcontains $extension) -and ([System.IO.Path]::GetFileName($relativePath) -ne 'CMakeLists.txt')) { continue }
  $bytes = [System.IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $relativePath).Path)
  if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xef -and $bytes[1] -eq 0xbb -and $bytes[2] -eq 0xbf) { throw "UTF-8 BOM: $relativePath" }
  for ($index = 0; $index -lt $bytes.Length; $index++) {
    if ($bytes[$index] -eq 0x0a -and ($index -eq 0 -or $bytes[$index - 1] -ne 0x0d)) { throw "Bare LF: $relativePath" }
    if ($bytes[$index] -eq 0x0d -and ($index + 1 -ge $bytes.Length -or $bytes[$index + 1] -ne 0x0a)) { throw "Bare CR: $relativePath" }
  }
}
Write-Host "CRLF/UTF-8 BOM validation passed for $($changed.Count) changed files."
exit 0
